<?php
$categories=db()->query('SELECT * FROM categories ORDER BY sort_order')->fetchAll();$colors=all_colors();$sizes=all_sizes();
$category=is_string($_GET['category']??null)?$_GET['category']:'';$color=filter_var($_GET['color']??0,FILTER_VALIDATE_INT)?:0;$size=filter_var($_GET['size']??0,FILTER_VALIDATE_INT)?:0;
$search=is_string($_GET['q']??null)?text_cut(trim($_GET['q']),80):'';
$min=is_numeric($_GET['min']??null)?max(0,(int)round((float)$_GET['min']*1000)):null;$max=is_numeric($_GET['max']??null)?max(0,(int)round((float)$_GET['max']*1000)):null;
$sort=is_string($_GET['sort']??null)?$_GET['sort']:'selection';$sorts=['selection'=>'p.sort_order','price-asc'=>'p.price_millimes IS NULL,p.price_millimes ASC','price-desc'=>'p.price_millimes IS NULL,p.price_millimes DESC','name'=>'p.name ASC'];
$where=['p.active=1'];$params=[];
if($category){$where[]='c.slug=?';$params[]=$category;}
if($search!==''){$where[]='p.name LIKE ?';$params[]='%'.$search.'%';}
if($min!==null){$where[]='p.price_millimes>=?';$params[]=$min;}
if($max!==null){$where[]='p.price_millimes<=?';$params[]=$max;}
if($color||$size){$v='EXISTS (SELECT 1 FROM variants v WHERE v.product_id=p.id AND v.stock>0';if($color){$v.=' AND v.color_id=?';$params[]=$color;}if($size){$v.=' AND v.size_id=?';$params[]=$size;}$where[]=$v.')';}
$s=db()->prepare('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE '.implode(' AND ',$where).' ORDER BY '.($sorts[$sort]??$sorts['selection']));$s->execute($params);$products=$s->fetchAll();
$activeFilters=(int)(bool)$category+(int)(bool)$color+(int)(bool)$size+(int)($min!==null)+(int)($max!==null)+(int)($search!=='');
?>
<main id="main"><section class="shop-heading"><p class="eyebrow">LE VESTIAIRE TASSURA</p><h1>Des lignes libres.<br><em>Un caractère singulier.</em></h1><p>Une collection pudique, un regard contemporain, une âme amazighe.</p></section>
<div class="shop-toolbar"><nav class="category-nav" aria-label="Catégories"><a class="<?=$category===''?'is-active':''?>" href="<?=e(route('shop'))?>">Tout le vestiaire</a><?php foreach($categories as $cat):?><a class="<?=$category===$cat['slug']?'is-active':''?>" href="<?=e(route('shop',['category'=>$cat['slug']]))?>"><?=e($cat['name'])?></a><?php endforeach;?></nav><div class="toolbar-end"><span><?=count($products)?> pièce<?=count($products)>1?'s':''?></span><button type="button" class="filter-trigger" data-filter-open>Filtrer & trier <?=$activeFilters?'('.$activeFilters.')':''?> <span aria-hidden="true">☷</span></button></div></div>
<dialog class="filter-dialog" data-filter-dialog><div class="dialog-heading"><h2>Affiner le regard</h2><button type="button" data-filter-close aria-label="Fermer les filtres">×</button></div><form class="filters" data-filter-panel method="get" action="<?=e(url('index.php'))?>"><input type="hidden" name="page" value="shop"><label class="field">Rechercher une pièce<input name="q" value="<?=e($search)?>" maxlength="80" type="search" placeholder="Nom de la pièce"></label><label class="field">Catégorie<select name="category"><option value="">Tout le vestiaire</option><?php foreach($categories as $cat):?><option value="<?=e($cat['slug'])?>" <?=$category===$cat['slug']?'selected':''?>><?=e($cat['name'])?></option><?php endforeach;?></select></label><label class="field">Coloris disponible<select name="color"><option value="">Tous les coloris</option><?php foreach($colors as $c):?><option value="<?=$c['id']?>" <?=$color===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label class="field">Taille disponible<select name="size"><option value="">Toutes les tailles</option><?php foreach($sizes as $s):?><option value="<?=$s['id']?>" <?=$size===$s['id']?'selected':''?>><?=e($s['label'])?></option><?php endforeach;?></select></label><fieldset class="price-filter"><legend>Prix en TND</legend><div class="form-grid"><label class="field">Minimum<input name="min" type="number" min="0" step="0.001" value="<?=$min!==null?e($min/1000):''?>"></label><label class="field">Maximum<input name="max" type="number" min="0" step="0.001" value="<?=$max!==null?e($max/1000):''?>"></label></div></fieldset><label class="field">Trier par<select name="sort"><?php foreach(['selection'=>'La sélection de la maison','price-asc'=>'Prix croissant','price-desc'=>'Prix décroissant','name'=>'Nom de la pièce'] as $key=>$label):?><option value="<?=e($key)?>" <?=$sort===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><div class="filter-actions"><a href="<?=e(route('shop'))?>">Tout effacer</a><button class="button" type="submit">Voir les pièces</button></div></form></dialog>
<?php if($products):?><div class="product-grid collection-grid"><?php foreach($products as $p)product_card($p);?></div><?php else:?><div class="empty-state"><h2>Une autre sélection vous attend.</h2><p>Aucune pièce disponible ne correspond à ces critères.</p><a class="button-outline" href="<?=e(route('shop'))?>">Réinitialiser les filtres</a></div><?php endif;?></main>